mapper.select:
SELECT department_id AS departmentId, meeting_type AS meetingType, in_valid_flag AS inValidFlag, SUM(duration) AS total FROM bbx_meeting_reserve WHERE 1 = 1
AND start_time BETWEEN #{beginTime} AND #{endTime}
AND department_id IN
#{deptId}
AND tenant_id = #{tenantId}
AND draft = 0 AND cancel_flag = 0 GROUP BY department_id, meeting_type, in_valid_flag ORDER BY department_id, meeting_type, in_valid_flag

SELECT department_id AS departmentId, meeting_type AS meetingType, in_valid_flag AS inValidFlag, COUNT(*) AS total FROM bbx_meeting_reserve WHERE 1 = 1
AND start_time BETWEEN #{beginTime} AND #{endTime}
AND department_id IN
#{deptId}
AND tenant_id = #{tenantId}
AND draft = 0 AND cancel_flag = 0 GROUP BY department_id, meeting_type, in_valid_flag ORDER BY department_id, meeting_type, in_valid_flag

SELECT in_valid_flag AS inValidFlag, SUM(duration) AS totalDurations, COUNT(*) AS totalMeetings FROM bbx_meeting_reserve WHERE 1=1
AND start_time BETWEEN #{beginTime} AND #{endTime}
AND department_id IN
#{deptId}
AND tenant_id = #{tenantId}
AND draft = 0 AND cancel_flag = 0 GROUP BY in_valid_flag

SELECT * FROM uic_department_member WHERE status = 0
AND department_id IN
#{deptId}

SELECT r.department_id departmentId, r.department_name departmentName, COALESCE(COUNT(DISTINCT r.id), 0) AS totalMeetings, COALESCE(SUM(r.in_valid_flag),0) AS invalidMeetings, COALESCE(SUM(r.duration), 0) AS totalDurations, COALESCE(SUM(sign_in.sign_count), 0) AS signInCount FROM bbx_meeting_reserve r LEFT JOIN (SELECT reserve_id,COUNT(DISTINCT id) AS sign_count FROM bbx_meeting_reserve_sign WHERE sign_time IS NOT NULL GROUP BY reserve_id ) sign_in ON r.id = sign_in.reserve_id WHERE r.draft = 0 AND r.cancel_flag = 0
AND r.start_time BETWEEN #{param.startTime} AND #{param.endTime}
AND r.tenant_id = #{param.tenantId}
AND r.department_id IN
#{deptId}
AND r.department_name LIKE CONCAT('%', #{param.departmentName}, '%')
GROUP BY r.department_id, r.department_name
ORDER BY ${param.sortBy}
${param.sortOrder}

SELECT r.id AS id, r.reserve_name AS reserveName, r.room_name AS roomName, r.in_valid_flag AS inValidFlag, r.duration AS durations, r.department_name AS departmentName, COUNT(sign_in.id) AS signInCount FROM bbx_meeting_reserve r LEFT JOIN bbx_meeting_reserve_sign sign_in ON r.id = sign_in.reserve_id AND sign_in.sign_time IS NOT NULL WHERE r.draft = 0 AND r.cancel_flag = 0
AND r.department_id IN
#{deptId}
AND r.department_id = #{param.departmentId}
AND r.start_time BETWEEN #{param.startTime} AND #{param.endTime}
AND r.reserve_name LIKE CONCAT('%', #{param.reserveNameLike}, '%')
AND r.in_valid_flag = #{param.inValidFlag}
AND r.tenant_id = #{param.tenantId}
GROUP BY r.id
ORDER BY ${param.sortBy}
${param.sortOrder}

SELECT DISTINCT ui.* FROM `uic_user_info` ui LEFT JOIN uic_tenant_member tm on tm.user_id = ui.id LEFT JOIN uic_department_member dm on dm.user_id = ui.id where ui.status != 2 and ui.identity = 1
AND tm.tenant_id= #{tenantId}
and dm.department_id = #{departmentId}
